<?php
/**
 * Default configuration. Do not edit this file on a server: create config.local.php next to it returning an
 * array with only the keys you want to change, e.g.  <?php return ['data_dir' => '/srv/calderone-data'];
 * The environment variable CALDERONE_DATA_DIR also overrides data_dir (useful for tests and the dev server).
 */
$config = [
    // Folder with all the JSON data and photos. Default: public/data (protected by its .htaccess).
    // On your own server prefer a folder OUTSIDE the web root.
    'data_dir' => __DIR__ . '/../data',

    // Feature modules, in any order (dependencies are resolved). "core" is always on.
    'modules' => ['recipes', 'collections', 'meallog', 'menus', 'shopping', 'ratings'],

    // Max photo upload size in bytes (the browser already shrinks photos to ~1600 px JPEG).
    'max_upload' => 8 * 1024 * 1024,

    // How many earlier versions of each recipe to keep (older ones are dropped).
    'history_max' => 100,

    // Time zone for "today" (meal diary, menus, shopping week).
    'timezone' => 'Europe/Rome',

    // Force the Secure flag on cookies (null = automatic: on when the request is HTTPS).
    'https_only' => null,
];

$local = __DIR__ . '/config.local.php';
if (is_file($local)) {
    $config = array_replace($config, require $local);
}
if (getenv('CALDERONE_DATA_DIR')) {
    $config['data_dir'] = getenv('CALDERONE_DATA_DIR');
}
return $config;
